function validate(input) {
  const [{ Listings = [] }] = input;
  const ids = new Set();
  for (const [id, city, price] of Listings) {
    if (id === null) return 'Every listing needs a listing_id.';
    if (ids.has(id)) return `listing_id ${id} appears twice.`;
    ids.add(id);
    if (city === null || city === '') return `Listing ${id} needs a city.`;
    if (!Number.isInteger(price)) return `Listing ${id} needs an integer price.`;
  }
  return null;
}

