function generate(rand, size) {
  const small = size === 'small';
  const pool = ['Austin', 'Boston', 'Chicago', 'Denver', 'LosAngeles', 'NewYork', 'SanFrancisco', 'Seattle'];
  const cities = small ? pool.slice(0, 2 + Math.floor(rand() * 3)) : Array.from({ length: 40 }, (_, i) => `City${String(i).padStart(2, '0')}`);
  // Small cases draw from a few round prices so city averages often equal the national average.
  const prices = [100, 200, 300, 400];
  const count = small ? Math.floor(rand() * 9) : 2000;
  const Listings = [];
  for (let i = 0; i < count; i++) {
    const city = cities[Math.floor(rand() * cities.length)];
    const price = small ? prices[Math.floor(rand() * prices.length)] : 100000 + Math.floor(rand() * 9900000);
    Listings.push([small ? 1 + i * 7 : i + 1, city, price]);
  }
  return [{ Listings }];
}
